package uk.ac.ravensbourne.casevault.service;
import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import uk.ac.ravensbourne.casevault.audit.AuditService; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.*; import uk.ac.ravensbourne.casevault.web.dto.CaseMutationRequests.*;
/** Mutations obtain the case through CaseAccessService before changing it (CWE-639). */
@Service public class CaseWorkflowService { private final CaseAccessService access; private final AccessPolicy policy; private final CaseRepository cases; private final UserAccountRepository users; private final CaseNoteRepository notes; private final RemediationActionRepository actions; private final InputNormalizer normalizer; private final AuditService audit; public CaseWorkflowService(CaseAccessService a,AccessPolicy p,CaseRepository c,UserAccountRepository u,CaseNoteRepository n,RemediationActionRepository r,InputNormalizer i,AuditService au){access=a;policy=p;cases=c;users=u;notes=n;actions=r;normalizer=i;audit=au;} @Transactional @RequiresCaseAccess public void assign(UserPrincipal p,UUID id,Assign request){var c=access.requireView(p,id);if(!policy.canAssign(p,c))throw new CaseNotFoundException();var analyst=users.findById(request.analystId()).orElseThrow(CaseNotFoundException::new);c.assign(analyst);audit.record(p,"CASE_ASSIGNED","CASE",id,"case-assigned");} @Transactional @RequiresCaseAccess public void status(UserPrincipal p,UUID id,Status request){var c=access.requireView(p,id);if(!policy.canChangeStatus(p,c))throw new CaseNotFoundException();CaseStatusMachine.requirePermitted(c.getStatus(),request.status());c.transitionTo(request.status());audit.record(p,"STATUS_CHANGED","CASE",id,"status-changed");} @Transactional @RequiresCaseAccess public void note(UserPrincipal p,UUID id,Note request){var c=access.requireView(p,id);if(!policy.canAddNote(p,c,cases.existsAssignment(id,p.id())))throw new CaseNotFoundException();notes.save(new CaseNote(UUID.randomUUID(),c,users.findById(p.id()).orElseThrow(),normalizer.text(request.body()),request.clientVisible()));audit.record(p,"NOTE_ADDED","CASE",id,"note-added");} @Transactional @RequiresCaseAccess public void action(UserPrincipal p,UUID id,Action request){var c=access.requireView(p,id);if(!policy.canAddRemediation(p,c,cases.existsAssignment(id,p.id())))throw new CaseNotFoundException();var action=new RemediationAction(UUID.randomUUID(),c,users.findById(p.id()).orElseThrow(),normalizer.text(request.description()));action.update(request.status());actions.save(action);audit.record(p,"ACTION_ADDED","CASE",id,"action-added");} public Page<CaseRecord> search(UserPrincipal p,String text,Category category,Severity severity,CaseStatus status,UUID owner,int page,int size,String sort){int safeSize=Math.min(Math.max(size,1),50);String field=Set.of("createdAt","title","severity","status").contains(sort)?sort:"createdAt";String q=text==null||text.isBlank()?null:"%"+text.toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";var pageable=PageRequest.of(Math.max(page,0),safeSize,Sort.by(Sort.Direction.DESC,field));Page<CaseRecord> result=switch(Role.valueOf(p.role())){case CLIENT_USER->cases.searchClient(p.organisationId(),q,category,severity,status,owner,pageable);case SECURITY_ANALYST->cases.searchAssigned(p.id(),q,pageable);case CASE_MANAGER->cases.findAll(pageable);case AUDITOR_ADMIN->Page.empty(pageable);};audit.record(p,"SEARCH_PERFORMED","CASE",null,"search-performed");return result;} }
